package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicFractionFamiliesTest {
 private static final int[] DEN={2,3,4,5,6,8,9,10,12,100};
 private static Question question(int n,int d,int b,int c){return new Question(FractionFamilies.ID,"같은 크기의 전체에서 색칠한 양이 같습니다. 두 분자를 쓰세요.\n"+n+"/"+d+" = □/"+b+" = □/"+c,"poison","poison");}
 @Test public void everySelectedConditionIgnoresStoredAnswersAndReportsOnlyWrongSlot(){
  int count=0;for(int d:DEN)for(int n=1;n<d;n++)for(int b:DEN)for(int c:DEN){if(d==b||d==c||b>=c||n*b%d!=0||n*c%d!=0)continue;Question q=question(n,d,b,c);int second=n*b/d,third=n*c/d;Checker checker=new Checker();assertTrue(checker.check(q,List.of(),List.of(""+second,""+third)).correct());for(int i=0;i<2;i++){List<String> wrong=new ArrayList<>(List.of(""+second,""+third));wrong.set(i,Integer.toString((i==0?second:third)+1));Checker.Result result=checker.check(q,List.of(),wrong);assertEquals(Checker.Status.WRONG_ANSWER,result.status);assertEquals(i,result.index);}q.diagram=new StudyDiagram("poison",new double[]{999});HelpPlan help=HelpPlan.forQuestion(q);assertEquals(6,help.size());assertFalse(help.canTransfer());assertTrue(help.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int[] entries={d,n,b,second,c,third};for(int i=0;i<6;i++)assertTrue(help.step(i).accepts(""+entries[i]));assertArrayEquals(new double[]{n,d,b,c},q.diagram.values,0);count++;}assertEquals(165,count);System.out.println("Public equivalent fraction family conditions="+count);
 }
 @Test public void selectedYearFiveHasHundredFreshFamiliesAndVisibleTenthsHundredths(){Generator gen=new Generator(new Random(176));List<String> recent=new ArrayList<>();boolean ten=false,hundred=false;for(int i=0;i<100;i++){Question q=gen.next(FractionFamilies.ID,recent,false,GlobalCurriculum.limits("england-primary-2021-v1",FractionFamilies.ID,5));assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=FractionFamilies.givens(q);assertNotNull(v);for(int j=1;j<4;j++){ten|=v[j]==10;hundred|=v[j]==100;}q.answers=new String[]{"999"};q.expression="999";assertTrue(new Checker().check(q,List.of(),List.of(""+(v[0]*v[2]/v[1]),""+(v[0]*v[3]/v[1]))).correct());}assertTrue(ten&&hundred);}
 @Test public void numericEquivalenceAndMissingInvalidSlotsRetainInputSemantics(){Question q=question(1,2,10,100);Checker checker=new Checker();assertTrue(checker.check(q,List.of(),List.of(" 5.0 ","100/2")).correct());for(List<String> answers:List.of(List.of("5",""),List.of("5","abc"),Arrays.asList("5",null),List.of("5","1/0"))) {Checker.Result r=checker.check(q,List.of(),answers);assertEquals(Checker.Status.INPUT_NEEDED,r.status);assertEquals(1,r.index);}assertEquals(Checker.Status.WRONG_ANSWER,checker.check(q,List.of(),List.of("5","-50")).status);for(String prompt:List.of("1/0 = □/10 = □/100","1/3 = □/10 = □/100","1/2 = □/10 = □/101","999999999999999999999/2 = □/10 = □/100")){q.prompt="같은 크기의 전체에서 색칠한 양이 같습니다. 두 분자를 쓰세요.\n"+prompt;assertNull(FractionFamilies.givens(q));assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of(),List.of("5","50")).status);}}
}
